  "dlgKoloryDruku.farbaMieszanaOsobnoNp": "Фарба, змішана окремо, напр. Pantone – у PDF це окрема форма. Введіть назву так, як її подає друкарня або віяло кольорів; CMYK поруч служить лише для перегляду на екрані. Новий додатковий колір можна також додати одразу в елементі – у виборі кольору або у Властивостях → «Оздоблення друку».",
