  "dlgKoloryDruku.lakierZlocenieTloczenieI": "Лак, золочення, тиснення й білу фарбу налаштовують в елементі: виберіть його й укажіть у Властивостях → «Оздоблення друку». Тут видно, що є в проєкті.",
