  "dlgKoloryDruku.rozszerzonyCmykNpCmyk": "Розширений CMYK (напр. CMYK + помаранчевий, зелений і фіолетовий) друкарня робить сама з вашого файлу – окрема палітра не потрібна. Біла фарба, лак, золочення й тиснення потрапляють у PDF як окремі форми з друком (друкарня бачить, де їх нанести).",
