  "eksportSerii.szablonIDaneDla": "Шаблон і дані для Scribus із плагіном ScribusGenerator (серійна розсилка).\n\nФайли:\n  szablon.sla – сторінки проєкту, кожна один раз; замість полів стоять змінні {pola}\n  dane.csv    – дані (UTF-8, кома); стовпці зображень містять шляхи obrazy/…\n  obrazy/     – зображення з даних\n\nУ Scribus: Скрипти → Виконати скрипт → ScribusGenerator, вкажіть szablon.sla і dane.csv, роздільник «,».\nЗмінні %VAR_стовпець% у текстах заміняться значеннями з наступних рядків.",
  "eksportSerii.szablonIDaneDo": "Шаблон і дані для злиття (серійної розсилки) у Word (а також у Publisher, у кого він ще є).\n\nФайли:\n  szablon.docx – сторінки проєкту з макетом (текстові рамки, зображення, фігури на своїх місцях) і полями злиття {pola}\n  dane.xlsx    – дані (аркуш «Dane»); те саме в dane.csv\n\nWord: відкрийте szablon.docx → Розсилки → Вибрати одержувачів → Використати наявний список → dane.xlsx →\n  Завершити й об'єднати. Поля вже є в тексті (MERGEFIELD).\nPublisher: Розсилки → Злиття → Використати наявний список → dane.xlsx, потім вставте поля зі списку.\n\nТекстові рамки – це текстові поля Word, прив'язані до сторінки, – після злиття кожен рядок даних стає наступною сторінкою\nз тим самим макетом. Таблиці, календарі й елементи з ефектами є зображеннями.",
  "eksportTekstu.spisTresci": "Зміст",
  "emailInny.wpiszInnyAdres": "Ввести іншу адресу",
  "emailOczekuje.kliknijLinkWWiadomosci": "Натисніть посилання в листі, надісланому на цю адресу. Доти ви входите з попередньою.",
  "emailOczekujeAnuluj.pomylkaZmianyNieDa": "Помилка? Скасувати зміну в застосунку не можна, але без натискання посилання нічого не станеться: посилання втратить чинність, а обліковий запис залишиться з поточною адресою. Можна також ввести іншу адресу – вона замінить цю.",
