  "sekcje.dodanoSekcjaMaStron": "Додано {brakuje} {ile} – розділ «{nazwa}» має {doPelnej} сторінок.",
  "sekcje.grafikaOkladkiSieNie": "{opis} Графіка обкладинки не друкується – на палітурному матеріалі залишаються елементи із золоченням або тисненням (Кольори для друку → Оздоблення). 3D-макет показує палітурний матеріал у вибраному кольорі.",
