  "skladankaNarzedzia.taLiniaNieDzieli2": "Ця лінія не ділить деталь на дві – проведіть її через деталь від краю до краю.",
  "skladankaNarzedzia.terazDrugiPunktNa": "Тепер друга точка на краю тієї самої деталі.",
