  "skladankaNarzedzia.tychCzesciNieDa": "Ці деталі не можна об'єднати в одну – після з'єднання вони накладалися б одна на одну (або краї мають різну довжину). Залиште їх окремо.",
  "skladankaNarzedzia.uwagaKrawedzILinia": " Увага: край і лінія відрізняються на {x} мм.",
