  "skladankaNarzedzia.wstawionoGdyCzesciNie": "Вставлено: {join}. Якщо деталі не поміщаються на аркуші, скористайтеся [Розкласти].",
  "skladankaNarzedzia.wybierzPlikObjAlbo": "Виберіть файл OBJ або STL.",
